/**  This one prompt. */
"prompt" | 
/**  The role file of the gloss type. */
"role" | 
/**  The course's `.lecter/course.jsonc`. */
"course" | 
/**  The global `config.jsonc`. */
"global" | 
/**  Lecter's built-in default. */
"default";

/**  One setting in force, as the Settings window lists it. */
