/** A command's name, as `invoke` takes it. */
export type CommandName = keyof Commands;

type CommandOk<R> = R extends { status: "ok"; data: infer T } ? T : R extends { status: "error" } ? never : R;
type CommandError<R> = R extends { status: "error"; error: infer E } ? E : never;
